import PropertyInstantInput from '@/components/property/PropertyInstantInput.vue'
import PropertyPartyPicker from '@/components/property/PropertyPartyPicker.vue'
import { formatDate } from '@/composables/useFormat'
import { chargeMoney as money } from '@/components/property/charges/chargeMoney'
import { appIsoDate } from '@/utils/date'
import { fundingCents, fundingDayEnd } from './fundingForm'
import { propertyDateInput as dateInput, propertyInput as input, propertyTextarea as textarea } from '@/components/property/propertyFormStyles'
import { propertyFundsApi as api, type FundingKind, type FundingClassification, type FundingKey, type FundingCommand, type FundingPreview, type FundingChoices, type FundingBalances, type FundingOperation, type FundingBankSource, type FundingCostSource, type FundingCoverageSource } from '@/api/propertyFunds'
const props = defineProps<{ supplier: number }>()
const { t } = useI18n(), auth = useAuthStore()
const date = ref(appIsoDate()), house = ref(0), knownAt = ref('')
const choices = ref<FundingChoices>({ houses: [], units: [], accounts: [] }), balances = ref<FundingBalances | null>(null), history = ref<FundingOperation[]>([])
const kind = ref<FundingKind>('draw'), classification = ref<FundingClassification>('repair'), amount = ref(''), evidence = ref(''), reason = ref(''), keyEvidence = ref(''), keyMode = ref<FundingKey['mode']>('at_accounting_date'), keyAt = ref(''), keyBasis = ref<FundingKey['legal_basis']>('management_share'), keyMethod = ref<FundingKey['method']>('share')
const costId = ref(0), bankId = ref(0), reverseId = ref(0), costs = ref<FundingCostSource[]>([]), banks = ref<FundingBankSource[]>([]), coverageSources = ref<FundingCoverageSource[]>([]), sourceNext = ref<number | null>(null), coverageNext = ref<number | null>(null), sourceIncomplete = ref(false)
const purposeEvidence = ref(''), dispositionEvidence = ref(''), target = ref<'long_term' | 'admin'>('long_term'), purpose = ref(''), due = ref(''), recipient = ref<number | null>(null), recipientName = ref(''), recipientAccount = ref(''), authority = ref('')
const advanceRows = ref<Array<{ source: string; amount: string }>>([]), dispositionRows = ref<Array<{ source: number; amount: string }>>([]), coverageRows = ref<Array<{ source: number; amount: string; evidence: string }>>([])
const busy = ref(false), error = ref(''), notice = ref(''), preview = ref<FundingPreview | null>(null), reviewed = ref<FundingCommand | null>(null), token = ref(''), acknowledged = ref(false), uncertain = ref(false)
let alive = true, generation = 0, edit = 0, sourceGeneration = 0
onBeforeUnmount(() => { alive = false; generation++; sourceGeneration++; edit++ })
function invalidate() { edit++; preview.value = null; reviewed.value = null; token.value = ''; acknowledged.value = false; uncertain.value = false }
const units = computed(() => choices.value.units.filter(unit => unit.parent_id === house.value))
const activeHistory = computed(() => history.value.filter(op => op.active && op.kind !== 'reverse'))
const advances = computed(() => (balances.value?.sources || []).filter(source => classification.value === 'administration' ? source.account_code === '324.200' : source.account_code.startsWith('955')))
const lots = computed(() => (balances.value?.income_lots || []).filter(lot => BigInt(lot.remaining_cents) > 0n))
const bankOptions = computed(() => banks.value.filter(bank => bank.direction === (kind.value === 'income' ? 'in' : 'out')))
const allowed = computed(() => !knownAt.value && auth.canWrite(kind.value === 'reverse' ? 'property.funds.reverse' : 'property.funds.post'))
const unitLabel = (id: number) => choices.value.units.find(unit => unit.id === id)?.code || t('propertyFunds.unit')
const advanceKey = (source: { kind: string; id: number }) => `${source.kind}:${source.id}`
function resetRows() { advanceRows.value = units.value.map(unit => ({ source: advances.value.find(source => source.unit_id === unit.id) ? advanceKey(advances.value.find(source => source.unit_id === unit.id)!.source) : '', amount: '' })); dispositionRows.value = []; coverageRows.value = [] }
const key = computed<FundingKey>(() => ({ mode: keyMode.value, at: keyMode.value === 'at_accounting_date' ? fundingDayEnd(date.value) : keyAt.value, method: keyBasis.value === 'management_share' ? 'share' : keyBasis.value === 'own_administration_equal' ? 'equal' : keyMethod.value, legal_basis: keyBasis.value, evidence_ref: keyEvidence.value }))
const command = computed<FundingCommand | null>(() => {
 if (!house.value || !date.value || balances.value?.revision === null || !evidence.value.trim() || !reason.value.trim()) return null
 const common = { house_id: house.value, accounting_date: date.value, expected_revision: balances.value?.revision ?? 0, evidence_ref: evidence.value, reason: reason.value }
 if (kind.value === 'reverse') return reverseId.value ? { ...common, kind: 'reverse', operation_id: reverseId.value } : null
 const cents = fundingCents(amount.value); if (!cents) return null
 if (kind.value === 'draw' || kind.value === 'income') {
  if (!key.value.at || !keyEvidence.value.trim()) return null
  if (kind.value === 'income') return bankId.value ? { ...common, kind: 'income', amount_cents: cents, key: key.value, bank_id: bankId.value } : null
  if (!costId.value || !purposeEvidence.value.trim()) return null
  const sources: Extract<FundingCommand, { kind: 'draw' }>['sources'] = []
  for (const row of advanceRows.value.filter(row => row.amount.trim())) { const source = advances.value.find(value => advanceKey(value.source) === row.source), value = fundingCents(row.amount); if (!source || !value) return null; sources.push({ source: source.source, amount_cents: value, purpose_evidence: purposeEvidence.value }) }
  const other: Extract<FundingCommand, { kind: 'draw' }>['other_coverage'] = []
  for (const row of coverageRows.value) { const value = fundingCents(row.amount); if (!row.source || !value || !row.evidence.trim()) return null; other.push({ line_id: row.source, amount_cents: value, evidence_ref: row.evidence }) }
  return sources.length ? { ...common, kind: 'draw', amount_cents: cents, key: key.value, classification: classification.value, ownership: 'owners_common_parts', cost_line_id: costId.value, sources, other_coverage: other } : null
 }
 if (!dispositionEvidence.value.trim()) return null
 const dispositions: Extract<FundingCommand, { kind: 'transfer' }>['dispositions'] = []
 for (const row of dispositionRows.value.filter(row => row.amount.trim())) { const lot = lots.value.find(lot => lot.id === row.source), value = fundingCents(row.amount); if (!lot?.parties || !value) return null; dispositions.push({ source_id: lot.id, amount_cents: value, party_ids: [...lot.parties.members], evidence_ref: dispositionEvidence.value, ...(authority.value.trim() ? { recipient_authority_ref: authority.value } : {}) }) }
 if (!dispositions.length) return null
 if (kind.value === 'transfer') return purpose.value.trim() && due.value ? { ...common, kind: 'transfer', amount_cents: cents, dispositions, target: target.value, purpose_ref: purpose.value, settlement_due_on: due.value } : null
 return bankId.value && recipient.value && recipientAccount.value.trim() ? { ...common, kind: 'payout', amount_cents: cents, dispositions, bank_id: bankId.value, recipient_id: recipient.value, recipient_account: recipientAccount.value } : null
})
watch(command, invalidate, { deep: true })
watch([kind, classification], () => { sourceGeneration++; costs.value = []; banks.value = []; coverageSources.value = []; costId.value = bankId.value = 0; sourceNext.value = coverageNext.value = null; sourceIncomplete.value = false; if (classification.value === 'administration' && kind.value === 'draw') keyBasis.value = 'own_administration_equal'; else if (keyBasis.value === 'own_administration_equal') keyBasis.value = 'management_share'; resetRows(); invalidate() })
watch([date, house, () => props.supplier], () => { sourceGeneration++; costs.value = []; banks.value = []; coverageSources.value = []; costId.value = bankId.value = reverseId.value = 0; invalidate(); void refresh() })
watch(knownAt, () => { generation++; sourceGeneration++; balances.value = null; history.value = []; costs.value = []; banks.value = []; resetRows(); invalidate() })
function message(caught: unknown) {
 const response = (caught as { response?: { status?: number; data?: { error?: { code?: string; message?: string } } } }).response, code = response?.data?.error?.code || ''
 const keys: Record<string, string> = { property_funding_capacity: 'capacity', property_funding_balance_capacity: 'capacity', property_funding_key_amount: 'keyMismatch', property_funding_source_owned: 'sourceUsed', property_funding_preview_stale: 'stale', property_funding_revision_conflict: 'stale', property_funding_idempotency_conflict: 'stale', property_funding_disposition_parties: 'originalOwners', property_funding_chronology: 'chronology', property_funding_cost_period: 'costPeriod', property_funding_advance_term: 'advanceTerm', property_payment_target_period_not_open: 'closed', property_payment_target_date_locked: 'closed', property_funding_reconciliation: 'reconciliationFailed' }
 return keys[code] ? t(`propertyFunds.${keys[code]}`) : code.startsWith('property_funding_') ? t('propertyFunds.unproven') : response?.data?.error?.message || t('propertyFunds.failed')
}
async function refresh() {
 const ticket = ++generation; busy.value = true; error.value = ''; invalidate()
 try {
  const catalog = await api.choices(props.supplier, date.value); if (!alive || ticket !== generation) return; choices.value = catalog
  const selected = catalog.houses.some(value => value.id === house.value) ? house.value : catalog.houses[0]?.id || 0
  if (selected !== house.value) { house.value = selected; return }
  if (!selected) { balances.value = null; history.value = []; return }
  const [read, records] = await Promise.all([api.balances(props.supplier, { date: date.value, house_id: selected, ...(knownAt.value ? { known_at: knownAt.value } : {}) }), api.list(props.supplier, selected)])
  if (!alive || ticket !== generation) return; balances.value = read; history.value = records.items; resetRows()
 } catch (caught) { if (alive && ticket === generation) { balances.value = null; history.value = []; error.value = message(caught) } }
 finally { if (alive && ticket === generation) busy.value = false }
}
async function loadSources(more = false) {
 const ticket = ++sourceGeneration, scope = generation; busy.value = true; error.value = ''; invalidate()
 try {
  if (kind.value === 'draw') { const page = await api.costs(props.supplier, date.value, classification.value, more ? sourceNext.value || 0 : 0); if (!alive || ticket !== sourceGeneration || scope !== generation) return; costs.value = more ? [...costs.value, ...page.items] : page.items; sourceNext.value = page.next_after_id; sourceIncomplete.value = page.incomplete.length > 0 }
  else { const page = await api.banks(props.supplier, date.value, more ? sourceNext.value || 0 : 0); if (!alive || ticket !== sourceGeneration || scope !== generation) return; banks.value = more ? [...banks.value, ...page.items] : page.items; sourceNext.value = page.next_after_id; sourceIncomplete.value = page.incomplete.length > 0 }
 } catch (caught) { if (alive && ticket === sourceGeneration && scope === generation) error.value = message(caught) }
 finally { if (alive && ticket === sourceGeneration && scope === generation) busy.value = false }
}
async function loadCoverages(more = false) { const ticket = ++sourceGeneration, scope = generation; busy.value = true; error.value = ''; invalidate(); try { const page = await api.coverages(props.supplier, date.value, more ? coverageNext.value || 0 : 0); if (!alive || ticket !== sourceGeneration || scope !== generation) return; coverageSources.value = more ? [...coverageSources.value, ...page.items] : page.items; coverageNext.value = page.next_after_id } catch (caught) { if (alive && ticket === sourceGeneration && scope === generation) error.value = message(caught) } finally { if (alive && ticket === sourceGeneration && scope === generation) busy.value = false } }
async function review() {
 if (!allowed.value || !command.value || busy.value) return
 const candidate = JSON.parse(JSON.stringify(command.value)) as FundingCommand; invalidate(); const version = edit, scope = generation; busy.value = true; error.value = ''
 try { const result = await api.preview(props.supplier, candidate); if (!alive || version !== edit || scope !== generation) return; preview.value = result; reviewed.value = candidate; token.value = crypto.randomUUID() }
 catch (caught) { if (alive && scope === generation) error.value = message(caught) }
 finally { if (alive && scope === generation) busy.value = false }
