 if (!allowed.value || !preview.value || !reviewed.value || !acknowledged.value || busy.value) return
 const scope = generation; busy.value = true; error.value = ''
 try { await api.execute(props.supplier, reviewed.value, preview.value, token.value); if (!alive || scope !== generation) return; invalidate(); amount.value = ''; notice.value = t('propertyFunds.done'); busy.value = false; await refresh() }
 catch (caught) { if (!alive || scope !== generation) return; if ([400, 401, 403, 404, 409, 422].includes((caught as { response?: { status?: number } }).response?.status || 0)) { invalidate(); error.value = message(caught) } else { uncertain.value = true; error.value = t('propertyFunds.uncertain') } }
 finally { if (alive && scope === generation) busy.value = false }
}
const toolbar = computed<ActionItem[]>(() => [{ key: 'refresh', label: t('propertyFunds.refresh'), icon: 'eye', variant: 'neutral', disabled: busy.value || !!preview.value, run: refresh }])
const sourcesActions = computed<ActionItem[]>(() => [{ key: 'sources', label: t('propertyFunds.loadSources'), icon: 'search', variant: 'neutral', disabled: busy.value || !!preview.value, run: () => loadSources() }, ...(sourceNext.value ? [{ key: 'more', label: t('propertyFunds.more'), icon: 'plus' as const, variant: 'neutral' as const, disabled: busy.value || !!preview.value, run: () => loadSources(true) }] : [])])
const actions = computed<ActionItem[]>(() => preview.value ? [{ key: 'confirm', label: t(uncertain.value ? 'propertyFunds.retry' : kind.value === 'reverse' ? 'propertyFunds.confirmReverse' : 'propertyFunds.confirm'), icon: 'checkCircle', variant: kind.value === 'reverse' ? 'danger' : 'success', tier: 'primary', disabled: busy.value || !acknowledged.value || !allowed.value, run: confirm }, { key: 'cancel', label: t('propertyFunds.cancel'), icon: 'x', variant: 'neutral', disabled: busy.value || uncertain.value, run: invalidate }] : [{ key: 'preview', label: t('propertyFunds.preview'), icon: 'eye', variant: 'primary', tier: 'primary', disabled: busy.value || !allowed.value || !command.value, run: review }])
const addRows = computed<ActionItem[]>(() => [{ key: 'add-source', label: t(kind.value === 'draw' ? 'propertyFunds.addAdvance' : 'propertyFunds.addDisposition'), icon: 'plus', variant: 'neutral', disabled: busy.value || !!preview.value || !allowed.value, run: () => kind.value === 'draw' ? advanceRows.value.push({ source: '', amount: '' }) : dispositionRows.value.push({ source: 0, amount: '' }) }])
