   <div class="grid gap-3 sm:grid-cols-3"><div v-for="(value, account) in balances.totals" :key="account" class="rounded border border-neutral-200 bg-surface p-3"><span class="font-medium">{{ account }}</span><p>{{ money(value) }} CZK</p><p class="text-xs text-neutral-500">{{ t('propertyFunds.ledger') }}: {{ money(balances.ledger_totals[account] || '0') }} CZK</p></div></div>
   <details><summary class="cursor-pointer text-sm">{{ t('propertyFunds.units') }}</summary><div class="grid gap-2 pt-2 sm:grid-cols-2 lg:grid-cols-3"><div v-for="(accounts, unit) in balances.unit_balances" :key="unit" class="rounded border border-neutral-200 bg-surface p-2"><strong>{{ unitLabel(Number(unit)) }}</strong><p v-for="(value, account) in accounts" :key="account">{{ account }}: {{ money(value) }} CZK</p></div></div></details>
  </section>
  <section v-if="house && balances" class="space-y-4 rounded-lg border border-neutral-200 bg-surface p-4">
