    <label class="flex min-w-0 flex-col gap-1 text-sm">{{ t('propertyFunds.operation') }}<select :disabled="busy || !!preview || !!knownAt" v-model="kind" :class="input" data-field="kind"><option v-for="value in (['draw','income','transfer','payout','reverse'] as const)" :key="value" :value="value">{{ t(`propertyFunds.${value}`) }}</option></select></label>
   <fieldset :disabled="busy || !!preview || !allowed" class="grid gap-3 sm:grid-cols-2">

    <label class="flex min-w-0 flex-col gap-1 text-sm" v-if="kind !== 'reverse'">{{ t('propertyFunds.amount') }}<input v-model="amount" inputmode="decimal" :class="input" data-field="amount" /></label>
    <label class="flex min-w-0 flex-col gap-1 text-sm" v-if="kind === 'draw'">{{ t('propertyFunds.classification') }}<select v-model="classification" :class="input" data-field="classification"><option v-for="value in (['repair','improvement','administration'] as const)" :key="value" :value="value">{{ t(`propertyFunds.${value}`) }}</option></select></label>
    <label class="flex min-w-0 flex-col gap-1 text-sm">{{ t('propertyFunds.evidence') }}<textarea v-model="evidence" :class="textarea" data-field="evidence" /></label><label class="flex min-w-0 flex-col gap-1 text-sm">{{ t('propertyFunds.reason') }}<textarea v-model="reason" :class="textarea" data-field="reason" /></label>
    <template v-if="kind === 'draw' || kind === 'income'">
     <label class="flex min-w-0 flex-col gap-1 text-sm">{{ t('propertyFunds.keyMode') }}<select v-model="keyMode" :class="input" data-field="key-mode"><option value="at_accounting_date">{{ t('propertyFunds.atAccountingDate') }}</option><option value="resolution_snapshot">{{ t('propertyFunds.resolutionSnapshot') }}</option></select></label>
