    <label v-if="kind === 'reverse'" class="sm:col-span-2 flex min-w-0 flex-col gap-1 text-sm">{{ t('propertyFunds.originalOperation') }}<select v-model.number="reverseId" :class="input" data-field="reverse"><option :value="0">{{ t('propertyFunds.choose') }}</option><option v-for="op in activeHistory" :key="op.id" :value="op.id">{{ formatDate(op.accounting_date) }} · {{ t(`propertyFunds.${op.kind}`) }} · {{ 'amount_cents' in op.request ? money(op.request.amount_cents) : '' }} CZK</option></select></label>
