   <template v-if="kind === 'draw'">
    <p v-if="classification !== 'administration'" class="text-sm text-neutral-500">{{ t('propertyFunds.foreignProperty') }}</p><label class="flex min-w-0 flex-col gap-1 text-sm">{{ t('propertyFunds.purposeEvidence') }}<textarea v-model="purposeEvidence" :disabled="busy || !!preview || !allowed" :class="textarea" data-field="purpose-evidence" /></label>
    <p class="text-sm text-neutral-500">{{ t('propertyFunds.sourceAmountsHelp') }}</p><fieldset :disabled="busy || !!preview || !allowed" class="space-y-2"><div v-for="(row, index) in advanceRows" :key="index" class="grid gap-2 rounded border border-neutral-200 bg-surface p-3 sm:grid-cols-[1fr_10rem_auto]"><label class="flex min-w-0 flex-col gap-1 text-sm">{{ t('propertyFunds.advanceSource') }}<select v-model="row.source" :class="input" :data-field="`advance-source-${index}`"><option value="">{{ t('propertyFunds.choose') }}</option><option v-for="source in advances" :key="advanceKey(source.source)" :value="advanceKey(source.source)">{{ unitLabel(source.unit_id) }} · {{ source.account_code }} · {{ money(source.amount_cents) }} CZK · {{ source.purpose_ref }}</option></select></label><label class="flex min-w-0 flex-col gap-1 text-sm">{{ t('propertyFunds.amount') }}<input v-model="row.amount" inputmode="decimal" :class="input" :data-field="`advance-amount-${index}`" /></label><button type="button" class="inline-flex h-9 w-9 shrink-0 cursor-pointer items-center justify-center self-end rounded-md text-neutral-400 hover:bg-danger-50 hover:text-danger-600 focus-visible:ring-2 focus-visible:ring-primary-400" :title="t('propertyFunds.remove')" :aria-label="t('propertyFunds.remove')" @click="advanceRows.splice(index, 1)"><svg viewBox="0 0 20 20" class="h-4 w-4" fill="none" stroke="currentColor" stroke-width="1.8" aria-hidden="true"><path d="m5 5 10 10M15 5 5 15" /></svg></button></div></fieldset><ActionBar :actions="addRows" />
    <details><summary class="cursor-pointer">{{ t('propertyFunds.otherCoverage') }}</summary><p class="py-2 text-sm text-neutral-500">{{ t('propertyFunds.otherCoverageHelp') }}</p><ActionBar :actions="coverageActions" /><fieldset :disabled="busy || !!preview || !allowed" class="space-y-2"><div v-for="(row, index) in coverageRows" :key="index" class="grid gap-2 rounded border border-neutral-200 bg-surface p-3 sm:grid-cols-3"><label class="flex min-w-0 flex-col gap-1 text-sm">{{ t('propertyFunds.coverageSource') }}<select v-model.number="row.source" :class="input" :data-field="`coverage-source-${index}`"><option :value="0">{{ t('propertyFunds.choose') }}</option><option v-for="source in coverageSources" :key="source.id" :value="source.id">{{ formatDate(source.entry_date || source.ledger.entry.entry_date) }} · {{ source.description || source.account_name || source.line.account_code }} · {{ source.line.account_code }} · {{ money(source.amount_cents) }} CZK</option></select></label><label class="flex min-w-0 flex-col gap-1 text-sm">{{ t('propertyFunds.amount') }}<input v-model="row.amount" inputmode="decimal" :class="input" :data-field="`coverage-amount-${index}`" /></label><label class="flex min-w-0 flex-col gap-1 text-sm">{{ t('propertyFunds.evidence') }}<input v-model="row.evidence" :class="input" :data-field="`coverage-evidence-${index}`" /></label><button type="button" class="inline-flex h-9 w-9 shrink-0 cursor-pointer items-center justify-center self-end rounded-md text-neutral-400 hover:bg-danger-50 hover:text-danger-600 focus-visible:ring-2 focus-visible:ring-primary-400" :title="t('propertyFunds.remove')" :aria-label="t('propertyFunds.remove')" @click="coverageRows.splice(index, 1)"><svg viewBox="0 0 20 20" class="h-4 w-4" fill="none" stroke="currentColor" stroke-width="1.8" aria-hidden="true"><path d="m5 5 10 10M15 5 5 15" /></svg></button></div></fieldset></details>
   </template>
   <template v-if="kind === 'transfer' || kind === 'payout'"><p class="text-sm text-neutral-500">{{ t('propertyFunds.originalOwners') }}</p><label class="flex min-w-0 flex-col gap-1 text-sm">{{ t('propertyFunds.dispositionEvidence') }}<textarea v-model="dispositionEvidence" :disabled="busy || !!preview || !allowed" :class="textarea" data-field="disposition-evidence" /></label><fieldset :disabled="busy || !!preview || !allowed" class="space-y-2"><div v-for="(row, index) in dispositionRows" :key="index" class="grid gap-2 rounded border border-neutral-200 bg-surface p-3 sm:grid-cols-[1fr_10rem_auto]"><label class="flex min-w-0 flex-col gap-1 text-sm">{{ t('propertyFunds.incomeLot') }}<select v-model.number="row.source" :class="input" :data-field="`disposition-source-${index}`"><option :value="0">{{ t('propertyFunds.choose') }}</option><option v-for="lot in lots" :key="lot.id" :value="lot.id">{{ unitLabel(lot.unit_id) }} · {{ formatDate(lot.accounting_date) }} · {{ lot.parties?.group_key }} · {{ lot.parties?.title_ref }} · {{ money(lot.remaining_cents) }} CZK</option></select></label><label class="flex min-w-0 flex-col gap-1 text-sm">{{ t('propertyFunds.amount') }}<input v-model="row.amount" inputmode="decimal" :class="input" :data-field="`disposition-amount-${index}`" /></label><button type="button" class="inline-flex h-9 w-9 shrink-0 cursor-pointer items-center justify-center self-end rounded-md text-neutral-400 hover:bg-danger-50 hover:text-danger-600 focus-visible:ring-2 focus-visible:ring-primary-400" :title="t('propertyFunds.remove')" :aria-label="t('propertyFunds.remove')" @click="dispositionRows.splice(index, 1)"><svg viewBox="0 0 20 20" class="h-4 w-4" fill="none" stroke="currentColor" stroke-width="1.8" aria-hidden="true"><path d="m5 5 10 10M15 5 5 15" /></svg></button></div></fieldset><ActionBar :actions="addRows" /></template>
   <section v-if="preview" data-section="preview" class="space-y-3 rounded border border-neutral-200 bg-surface p-3"><h2 class="font-semibold">{{ t('propertyFunds.reviewTitle') }}</h2><p>{{ t('propertyFunds.previewOnly') }}</p><div class="grid gap-2 sm:grid-cols-3"><div v-for="(line, index) in preview.plan.journal.lines" :key="index" class="rounded border border-neutral-200 bg-surface p-2"><strong>{{ line.account_code }}</strong> · {{ t(`propertyFunds.${line.side}`) }}<p>{{ line.amount }} CZK</p></div></div><div class="grid gap-2 sm:grid-cols-3"><p v-for="(effect, index) in preview.plan.effects" :key="index">{{ unitLabel(effect.unit_id) }} · {{ effect.account_code }} · {{ money(effect.amount_cents) }} CZK</p></div><label class="flex flex-wrap items-center gap-2"><input v-model="acknowledged" type="checkbox" :disabled="busy || !allowed" data-field="ack" />{{ t('propertyFunds.ack') }}</label></section>
   <ActionBar :actions="actions" />
  </section>
  <section v-if="history.length" class="space-y-3 rounded-lg border border-neutral-200 bg-surface p-4"><h2 class="font-semibold">{{ t('propertyFunds.history') }}</h2><div class="grid gap-3 md:grid-cols-2"><article v-for="op in history" :key="op.id" class="space-y-1 rounded border border-neutral-200 bg-surface p-3"><strong>{{ t(`propertyFunds.${op.kind}`) }}</strong><p>{{ formatDate(op.accounting_date) }} · {{ 'amount_cents' in op.request ? money(op.request.amount_cents) : '' }} CZK</p><span class="inline-flex rounded border border-neutral-200 px-2 py-1 text-xs" :class="op.active ? 'text-success-700' : 'text-neutral-500'">{{ t(op.active ? 'propertyFunds.posted' : 'propertyFunds.reversed') }}</span><p class="text-sm text-neutral-500">{{ op.request.evidence_ref }}</p></article></div></section>
 </div>
</template>
